#pragma once
#include "animation.hpp"
#include <obs.h>
namespace spatial {
inline Animation readParameterAnimation(obs_data_t*d){Animation a;auto*arr=obs_data_get_array(d,"animation");if(arr)for(size_t i=0;i<obs_data_array_count(arr);++i){auto*r=obs_data_array_item(arr,i);std::string id=obs_data_get_string(r,"parameter");if(!id.empty()&&id.size()<=128){Curve c;c.enabled=obs_data_get_bool(r,"enabled");c.locked=obs_data_get_bool(r,"locked");c.shortest=obs_data_get_bool(r,"shortest");auto*keys=obs_data_get_array(r,"keys");if(keys)for(size_t j=0;j<obs_data_array_count(keys);++j){auto*k=obs_data_array_item(keys,j);AnimKey key;try{key.time=std::stoll(obs_data_get_string(k,"time_us"));}catch(...){key.time=0;}key.value=obs_data_get_double(k,"value");key.interpolation=Interpolation(std::clamp(int(obs_data_get_int(k,"mode")),0,7));key.legacyFrom=obs_data_has_user_value(k,"legacy_from")?obs_data_get_double(k,"legacy_from"):0;key.legacyTo=obs_data_has_user_value(k,"legacy_to")?obs_data_get_double(k,"legacy_to"):1;key.outAbsolute=obs_data_get_bool(k,"out_absolute");key.inAbsolute=obs_data_get_bool(k,"in_absolute");key.outX=obs_data_has_user_value(k,"out_x")?obs_data_get_double(k,"out_x"):1.0/3;key.outY=obs_data_has_user_value(k,"out_y")?obs_data_get_double(k,"out_y"):1.0/3;key.inX=obs_data_has_user_value(k,"in_x")?obs_data_get_double(k,"in_x"):2.0/3;key.inY=obs_data_has_user_value(k,"in_y")?obs_data_get_double(k,"in_y"):2.0/3;if(!std::isfinite(key.outX))key.outX=1.0/3;if(!std::isfinite(key.outY))key.outY=1.0/3;if(!std::isfinite(key.inX))key.inX=2.0/3;if(!std::isfinite(key.inY))key.inY=2.0/3;c.put(key);obs_data_release(k);}obs_data_array_release(keys);a[id]=std::move(c);}obs_data_release(r);}obs_data_array_release(arr);return a;}
inline void writeParameterAnimation(obs_data_t*d,const Animation&a){auto*arr=obs_data_array_create();for(auto&pair:a){auto*r=obs_data_create();obs_data_set_string(r,"parameter",pair.first.c_str());auto&c=pair.second;obs_data_set_bool(r,"enabled",c.enabled);obs_data_set_bool(r,"locked",c.locked);obs_data_set_bool(r,"shortest",c.shortest);auto*keys=obs_data_array_create();for(auto&k:c.keys()){auto*v=obs_data_create();obs_data_set_string(v,"time_us",std::to_string(k.time).c_str());obs_data_set_double(v,"value",k.value);obs_data_set_int(v,"mode",int(k.interpolation));obs_data_set_double(v,"legacy_from",k.legacyFrom);obs_data_set_double(v,"legacy_to",k.legacyTo);obs_data_set_bool(v,"out_absolute",k.outAbsolute);obs_data_set_bool(v,"in_absolute",k.inAbsolute);obs_data_set_double(v,"out_x",k.outX);obs_data_set_double(v,"out_y",k.outY);obs_data_set_double(v,"in_x",k.inX);obs_data_set_double(v,"in_y",k.inY);obs_data_array_push_back(keys,v);obs_data_release(v);}obs_data_set_array(r,"keys",keys);obs_data_array_release(keys);obs_data_array_push_back(arr,r);obs_data_release(r);}obs_data_set_array(d,"animation",arr);obs_data_array_release(arr);}
}
